import os
from typing import Tuple

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    normalized_cmd = []
    for item in cmd:
        if not os.path.isfile(item):
            # Handle cases where the first item is a symbolic link or not a file.
            normalized_cmd.append(item)
        else:
            if item.startswith('#!'):
                # For Windows, shebangs need to be quoted if they contain spaces.
                # Otherwise, they might be parsed as another command.
                item = item[2:]
                normalized_cmd.append('"{}'.format(item))
            else:
                normalized_cmd.append(item)
    return tuple(normalized_cmd)

