def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not inspect.isfunction(func):
        raise ValueError('The @ttl_cache decorator must be applied innermost of all decorators.')

    def _ttl_cache_cache(f):
        cache = collections.OrderedDict()
        result_factory = IntegralResult(default_cache=dict(ttl=ttl))

        def _insert(item, ttl):
            # Seconds since last access.
            ttl = datetime.timedelta(seconds=ttl)
            cache[item] = (ttl, timer())

        def _getitem(item):
            ttl, last_access = cache.get(item, (datetime.timedelta(), 0))

            # Ignore cached items that have expired.
            if datetime.datetime.now() - last_access > ttl:
                return None

            del cache[item]  # Remove item from cache before accessing
            # item
            return result_factory(result_factory.wrap(f(item)), cache)

        def _iteritems():
            for item, (ttl, last_access) in cache.items():
                # TTL is calculated from the last access because we want
                # to find items that would be expired soon.
                now = datetime.datetime.now()
                last_access = max(last_access, now - datetime.timedelta(seconds=ttl))
                if now - last_access > ttl:
                    continue  # Ignore cached items that have expired.
                yield item, result_factory(result_factory.wrap(f(item)), cache)

        def _items():
            return tuple(_iteritems())

        def _setter(item, result=None):
            if not isinstance(item, f.__annotations__.get('argtypes', (keys.hashkey,))):
                # The item is not a valid key, so we can't cache it.
                return

            # Set the cache entry with an expiration timestamp.
            _insert(item, ttl)

            if result:
                setattr(item, '_ttl_cache_result', result)

        def _copy(item):
            result = _getitem(item)
            return item._ttl_cache_result if result else None

        def _clear():
            cache.clear()

        def _ttl expired(item):
            return _getitem(item) is None

        return types.MethodType(_getitem, f), types.MethodType(_items,

