import collections
from contextlib import contextmanager

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is None:
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper
        return decorator

    if typed:
        def memoized_storage(key):
            return {}
        KVStore = collections.OrderedDict
    else:
        def memoized_storage(key):
            return set()
        KVStore = collections.deque

    storage = memoized_storage(memoized_storage(frozenset))

    @functools.wraps(func)
    def memoize(*args, **kwargs):
        key = (frozenset(args), frozenset(kwargs.items())) if typed else (args, kwargs)
        if key in storage:
            return storage[key]
        result = func(*args, **kwargs)
        if len(storage) == maxsize:
            if typed:
                storage.popitem(last=False)
            else:
                storage.pop()
        storage[key] = result
        return result

    @contextmanager
    def put(*args, **kwargs):
        key = (frozenset(args), frozenset(kwargs.items())) if typed else (args, kwargs)
        yield functools.partial(memoized_storage.__setitem__, key)
    memoize.put = put

    return memoize

