def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections.deque import deque

    class LRUCache:
        def __init__(self, maxsize=128, typed=False):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.order = deque()

        def __setitem__(self, key, value):
            if key in self.cache:
                self.order.remove(key)
            elif len(self.cache) >= self.maxsize:
                self.cache.pop(next(iter(self.order)))
            self.order.append(key)
            self.cache[key] = value

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]

        def getsizeof(self, obj, key, default):
            if self.typed:
                return sys.getsizeof(obj, key)
            else:
                return sys.getsizeof(obj)

    def decorator(func):
        if func is None:
            return functools.partial(lfu_cache, maxsize=maxsize, typed=typed)
        return functools.wraps(func)(LRUCache(maxsize=maxsize, typed=typed))

    return decorator

