from abc import ABC, abstractmethod

class Ordering(ABC):
    @abstractmethod
    def is_before(self, other: 'Ordering') -> bool:
        pass

class LeafOrdering(Ordering):
    def __init__(self, value):
        self.value = value

    def is_before(self, other: 'Ordering') -> bool:
        return False

class PrefixOrdering(Ordering):
    def __init__(self, root: 'LeafOrdering', value):
        self.root = root
        self.value = value

    def __eq__(self, other):
        return self.root == other.root and self.value == other.value

    def is_before(self, other: 'Ordering') -> bool:
        # Allow any shorter prefixes to be "before" a longer prefix
        if isinstance(other, LeafOrdering):
            return other.value < self.value
        if isinstance(other, PrefixOrdering):
            return self.root.value < other.value or (self.root.value == other.root.value and other.value < self.value)

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    def get_parent(node):
        if not node:
            return None
        if node.root.value > node.value:
            return node.root
        return get_parent(node.root)

    def get_children(node):
        if not node.children:
            return []
        return sorted(node.children, key=lambda child: child.value)

    def add_node(node, value):
        # Ignore existing nodes with the same value
        if node.value == value:
            return
        if node.root is None:
            parent = LeafOrdering(value)
        else:
            parent = get_parent(node)
        child = LeafOrdering(value) if value not in node.value_set else PrefixOrdering(parent, value)

