def minimalBases(classes):
    bases = list(classes)
    while len(bases) > 1:
        smaller_clazz = None
        for i in range(len(bases) - 1, -1, -1):
            current_base = bases[i]
            for j in range(i - 1, -1, -1):
                next_base = bases[j]
                if len(current_base.__bases__) < len(next_base.__bases__):
                    smaller_clazz = next_base
                    break
            if smaller_clazz is not None:
                break
        if smaller_clazz is None:
            break
        bases.remove(smaller_clazz)
    return bases

