def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not self.fixity:
        raise ValueError('Fixity block is empty')

    if isinstance(fixity, dict):
        for key, value in fixity.items():
            if not value:
                raise ValueError(f'Fixity entry "{key}" is empty')
            if key in manifest_files:
                manifest_files.remove(key)
            else:
                raise ValueError(f'Fixity entry "{key}" references an unlisted file: {key}')
    else:
        raise ValueError('Fixity block is not in the correct format')

    if manifest_files:
        raise ValueError('Some files listed in the manifest are not referenced')

    print("Fixity block is valid:", file=sys.stderr)

