def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    start_time = time.time()
    objects = self.get_storage_root_hierarchy()
    num_objects = len(objects)

    if start_time == 0:
        start_time = time.time()

    if num_objects is 0:
        if (show_warnings):
            print("Warning: No storage root hierarchy found.")
    else:
        if validate_objects:
            for i, obj in enumerate(objects):
                result = obj.validate()
                if not result:
                    return i + 1, i + 1
            if (show_warnings):
                print("Warning: All storage root hierarchy objects were validated.")
        if check_digests:
            for i, obj in enumerate(objects):
                if not obj.check_digests():
                    return i + 1, i + 1
            if (show_warnings):
                print("Warning: All storage root hierarchy objects' digests were checked.")

    end_time = time.time()
    milliseconds = (end_time - start_time) * 1000
    if (show_warnings):
        print("Action taken for {0} objects in {1:.2f} milliseconds.".format(num_objects, milliseconds))
    return num_objects, good_objects

