def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    inventory_check = []
    inventory_dicts = {}
    for version_dir in version_dirs:
        p = os.path.join(os.getcwd(), version_dir)
        if not os.path.isdir(p):
            raise FileNotFoundError(position=p, oftype=Directory)
        vendoring_inventory_json = os.path.join(p, 'vendoring_inventory.json')
        if not os.path.isfile(vendoring_inventory_json):
            raise FileNotFoundError(position=p, oftype=File)
        inventory_json = os.path.join(p, 'inventory.json')
        if not os.path.isfile(inventory_json):
            raise FileNotFoundError(position=p, oftype=File)
        vendoring_inventory_dicts = json.load(open(vendoring_inventory_json))
        inventory_dicts[p] = vendoring_inventory_dicts
    inventories_version = sorted(inventory_dicts.keys(), key=int)
    repo_inventory = json.load(open(os.path.join(os.getcwd(), 'inventory.json')))
    digest_dict = {}
    content_check = []
    for item in repo_inventory['items']:
        content digest_dict[item['content_digest']] = 1
    for version in inventories_version:
        updated_inventory = inventory_dicts[version]
        for item in updated_inventory['items']:
            content_digest_dict[item['content_digest']] = 1
            if item['content_digest'] not in content_check:
                content_check.append(item['content_digest'])
            if item['content_digest'] != repo_inventory['items'][item['parent_index']][
                'content_digest']:
                inventory_check.append(item)
    if len(content_check) > 0:
        msg = "There are content digest differences at рынке inventory. Please check "
        raise ValueError(msg + '\n' + ', '.join(content_check))
    return inventory_check

