import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    def windows_split(s):
        # Windows-specific implementation using backslashes as separators
        return re.split(r'\\', s)

    def posix_split(s):
        # POSIX-specific implementation using either commas or space as separators
        return re.split(r'[ ,]+', s)

    # Determine the split function based on the platform
    if platform == 'this':
        platform = sys.platform
    if platform == 'windows' or platform == 'cmd':
        split_func = windows_split
    else:
        split_func = posix_split

    # Perform the bash-like split, treating empty strings as delimiters
    return [item for item in split_func(s).split(',') if item]

