def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f'Archive {archive_path} does not exist.')

    # Unzip the archive
    try:
        subprocess.run(['unzip', archive_path], cwd=tmp_path, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f'Failed to unzip {archive_path}: {e}')

    # Find the archive inside the temp directory
    for root, dirs, files in os.walk(tmp_path):
        for file in files:
            if file.endswith(('.tar.gz', '.tar.bz2')):
                archive_path = os.path.join(root, file)

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f'Archive is not found in the temp directory.')

    # Extract the contents of the archive to a temporary directory
    temp_extract_dir = Path(temp_path, filename or 'extracted_files')
    temp_extract_dir.mkdir(parents=True, exist_ok=True)
    collectdir = str('.'.join(archive_path.split('.')[0:2])) if archive_path.endswith('.tar.gz') else '.'

    os.system(f'decho \'Collecting {collectdir}\' make')
    os.system(f'decho \'Untarring to {collectdir}\' tar  -C {temp_extract_dir} -xzf {archive_path}')

    # Remove the temp extraction directory
    os.system(f'decho \'Removing temporary directory\' rm -rf {temp_extract_dir}')

    # Check if the archive type is .tar.gz or .tar.bz2 and serve the file accordingly
    archive_type = self.get_primary_archive_type(archive_path)
    if archive_type == '.tar.gz':
        return self.repourl_for_file(archive_path)
    elif archive_type == '.tar.bz2':
        return self.repourl_for_file(archive_path)
    else:
        return "Unsupported archive type"

