from functools import wraps

@wraps(cls.protocol_handlers)
def protocol_handlers(cls, protocol_version=None):
    if not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be a tuple")
    handlers = {}
    for protocol in cls.__dict__.values():
        if callable(protocol) and hasattr(protocol, '_protocol_version'):
            protocols_version = protocol._protocol_version
            if not isinstance(protocols_version, tuple):
                raise TypeError("Protocol version must be a tuple")
            if protocol_version <= protocol_version:
                handlers[protocols_version] = protocol
    if protocol_version is None:
        return handlers
    if protocol_version not in handlers:
        return {}
    return {protocol_version: handlers[protocol_version]}

