def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    for base in bases:
        try:
            for baseobj in base.infer():
                if isinstance(baseobj, ClassDef) and baseobj.hide:
                    assert isinstance(baseobj._metaclass, tuple), (
                        'Class definition for meta needs to specify both __metaclass__ and '
                        '__metaclass_ucls__ (using tuple).'
                    )
                    if not explicit_mc:
                        explicit_mc = baseobj._metaclass
                    if not isinstance(explicit_mc, tuple):
                        explicit_mc = (explicit_mc,)
                    break
        except exceptions.InferenceError:
            pass

    if explicit_mc:
        if not isinstance(explicit_mc, tuple):
            explicit_mc = (explicit_mc,)
        # Returns first metaclass or None if all metaclasses are the same
        return tuple(set(explicit_mc))[-1] if explicit_mc != () else None
    else:
        # Returns first metaclass or None if no base metaclasses
